const { messages, status, stop, reload } = useChat();
const last = messages.at(-1);
<StreamingText
  text={last?.role === "assistant" ? last.content : ""}
  status={status}
  question={messages.at(-2)?.content}
  assistant={{ name: "Helper", role: "Support" }}
  height={0}
  onStop={stop}
  onRetry={reload}
  onRegenerate={reload}
/>
